"""Native500 complete-minimum refinement for the second, explicitly exploratory
pooling hypothesis. Power 2 fixed before noise-cache examination.
"""
from verify_mean_cv import *

class SkillSquared(MeanCV):
    def evaluate(self,p,h,kind="cv",details=False):
        channels=super().evaluate(p,h,kind,details=True)
        if details:return channels
        return -float(np.sum(np.maximum(0,1-channels)**2))

def verify(case):
    t,g,w,y,off,cfg=read_case(case,aggregate=False)
    off=off if cfg["los_phase_compensation"] else np.zeros_like(t)
    ev=SkillSquared(t,g,w,y,off)
    grid=np.sort(1/np.linspace(1/cfg["period_max_s"],1/cfg["period_min_s"],cfg["period_grid_size"]))
    result={"case":case,"utc":datetime.now(timezone.utc).isoformat(),
        "rule":"native500 positive CV skill squared sum; H selected among 1,2,4,8; exploratory comparison",
        "harmonics":[]}
    for h in HYPOTHESES:
        record=search(ev,grid,h)
        result["harmonics"].append(record)
        (OUT/f"{case}_native500_skill2.json").write_text(json.dumps(result,indent=2),encoding="utf-8")
        print(case,h,json.dumps(record["candidates"][0]),flush=True)
    win=min(result["harmonics"],key=lambda r:(r["candidates"][0]["score"],r["h"]))
    result["selected"]={"h":win["h"],**win["candidates"][0]}
    result["script_sha256"]=hashlib.sha256(Path(__file__).read_bytes()).hexdigest()
    (OUT/f"{case}_native500_skill2.json").write_text(json.dumps(result,indent=2),encoding="utf-8")
    print("SELECTED",case,json.dumps(result["selected"]),flush=True)
if __name__=="__main__":
    for case in sys.argv[1:] or list(CASES):verify(case)

