from pathlib import Path
import hashlib,json,datetime
OUT=Path(__file__).parent
ROOT=OUT.parents[2]
def sha(path):
    h=hashlib.sha256()
    with path.open('rb') as stream:
        for part in iter(lambda:stream.read(1<<20),b''):h.update(part)
    return h.hexdigest()
inputs=[]
for tag in ['70m','400m']:
    for name in ['clean_features.npy','design.npz','features.npy','extraction.json']:
        p=ROOT/f'tmp/receiver_snr_ev5_{tag}_20261016'/name
        inputs.append({'path':str(p.relative_to(ROOT)),'sha256':sha(p),'size_bytes':p.stat().st_size})
for p in [ROOT/'echo/src/echo.py',ROOT/'docs/4.3/vs_4.2/experiments/configs/2026-10-16_EV5_70M.json']:
    inputs.append({'path':str(p.relative_to(ROOT)),'sha256':sha(p),'size_bytes':p.stat().st_size})
selected=[]
for p in sorted(OUT.glob('*full500_all_train*.json')):
    d=json.loads(p.read_text());r=min(d['results'],key=lambda r:r['top10'][0]['cv_mean'])
    selected.append({'source':p.name,'degree':r['degree'],**r['top10'][0]})
